interface DiscountPolicy {
    double applyDiscount(double price, int quantity);
}

class QuantityDiscountPolicy implements DiscountPolicy {
    public double applyDiscount(double price, int quantity) {
        if (quantity >= 10) return price * 0.9; // 10% rabatu od 10 sztuk
        return price;
    }
}

// WERSJA 1: wszystko w 1 metodzie - Big Ball of Mud w miniaturze
class BigBallOfMudShop {
    private Map<String, Double> database = new HashMap<>();

    String handleOrder(String orderId, double price, int quantity) {
        double finalPrice = quantity >= 10 ? price * 0.9 : price; // logika rabatu
        database.put(orderId, finalPrice);                       // "zapis do bazy"
        return "Zamowienie " + orderId + ": " + finalPrice + " PLN"; // formatowanie odpowiedzi
    }
}

// WERSJA 2: wyrazne granice miedzy odpowiedzialnosciami
interface OrderRepository {
    void save(String orderId, double finalPrice);
}

class InMemoryOrderRepository implements OrderRepository {
    private final Map<String, Double> storage = new HashMap<>();
    public void save(String orderId, double finalPrice) { storage.put(orderId, finalPrice); }
}

class OrderService {
    private final DiscountPolicy discountPolicy;
    private final OrderRepository repository;

    OrderService(DiscountPolicy discountPolicy, OrderRepository repository) {
        this.discountPolicy = discountPolicy;
        this.repository = repository;
    }

    String placeOrder(String orderId, double price, int quantity) {
        double finalPrice = discountPolicy.applyDiscount(price, quantity);
        repository.save(orderId, finalPrice);
        return "Zamowienie " + orderId + ": " + finalPrice + " PLN";
    }
}

// ZLE: logika biznesowa (rabat) nierozerwalnie zrosnieta z technicznym szczegolem (zapis)
class MudOrderHandler {
    private final Map<String, Double> database = new HashMap<>();

    void handle(String orderId, double price, int quantity) {
        double finalPrice;
        if (quantity >= 10) {
            finalPrice = price * 0.9;
        } else {
            finalPrice = price;
        }
        database.put(orderId, finalPrice); // rabat i zapis w tej samej metodzie - nie da sie przetestowac osobno
    }
}

// DOBRZE: regula biznesowa wydzielona, testowalna w calkowitej izolacji
class QuantityDiscountPolicyTest {
    public static void main(String[] args) {
        DiscountPolicy policy = new QuantityDiscountPolicy();

        assertEquals(100.0, policy.applyDiscount(100.0, 5));   // ponizej progu - bez rabatu
        assertEquals(90.0, policy.applyDiscount(100.0, 10));   // od 10 sztuk - 10% rabatu
        System.out.println("Testy przeszly - bez bazy danych, bez sieci, bez frameworka");
    }

    static void assertEquals(double expected, double actual) {
        if (Math.abs(expected - actual) > 0.001) throw new AssertionError(expected + " != " + actual);
    }
}
